const track0 = {
  color: '#8fd08f',
  graph: x => { const m = leadAt(x); return m ? 1.1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = leadAt(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["P = \\text{чантер: } r_{\\text{гобой}}(f) + \\text{бурдоны } \\sum_{k=1}^{3} \\sin 2\\pi\\,2^{-k} f_{\\text{тоника}} t\\ (\\text{тенор, баритон, бас})"],
  audio({ bpm }) {
    const sec = 60 / bpm, ch = reed({ kind: 'oboe', breath: 0.05 }), dr = organ({ voices: 3, stops: [[1, 1], [2, 0.5], [3, 0.3], [4, 0.2], [5, 0.12]], chiff: 0.05, gain: 0.05 }), verb = reverb({ room: 0.8, damp: 0.4, wet: 0.3 })
    const T = (TONIC => [TONIC - 24, TONIC - 36, TONIC - 12])(9 + 48)
    let n = 0
    return x => {
      const m = leadAt(x)
      if (m) n = m.n
      const playing = x < END - 1 && energy(x) >= 1
      const [l, r] = dr(playing ? T.map(t => hz(t - 60, C4)) : [])
      const y = 0.42 * ch(hz(n, C4), !!m && m.u < 0.95, 0.4)
      return verb(...pan(y, 0.12).map((v, i) => v + (i ? r : l)))
    }
  },
}

